import os,sys,json,base64,zlib,hashlib,shutil
from pathlib import Path
code=Path('/kaggle/working/code');code.mkdir()
for name,value in json.loads(zlib.decompress(base64.b64decode(''))).items():
 p=code/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(value)
os.environ['PYTHONPATH']=str(code/'src')+':'+str(code);sys.path[:0]=[str(code/'src'),str(code)]
import numpy as np,torch,requests
from scipy.io import loadmat
from p3a.attacks.adaptive_evasion import project_applied_delta
from p3a.data.loaders.openbmi import build_trials
from p3a.data.openbmi_release import execution_code_hashes,load_execution_release
revision='260771bbba8087e3644cf889afb9811d6bce0761';out=Path('/kaggle/working/out');out.mkdir();old=code/'splits/openbmi_independent_20261022'
digest=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
ph=digest(old/'protocol.json');portable=json.loads((code/'evidence/portable_config.json').read_text());assert portable['returncode']==0 and portable['git_commit']=='03f0b8918d812d59c9f1864ceb99acffc7050c57'
oldreceipt=json.loads((old/'receipt_s37.json').read_text());newhash=execution_code_hashes(code)
assert set(newhash)==set(oldreceipt['execution_code_sha256'])
changes=[k for k in newhash if newhash[k]!=oldreceipt['execution_code_sha256'][k]]
assert set(changes)=={'src/p3a/attacks/adaptive_evasion.py','scripts/evaluate_openbmi_independent_attacks.py'},changes
root=Path('/kaggle/input')
def unique(name):
 paths=list(root.rglob(name));assert len(paths)==1,(name,len(paths));return paths[0]
sp=unique('budget_summary.json');dp=unique('strict_budget_diagnostic.json');summary=json.loads(sp.read_text());diagnostic=json.loads(dp.read_text())
assert summary['all_equal_float32_epsilon'] and summary['strict_violations']==len(diagnostic['violations'])==13419
assert summary['candidate_projection_checks']['status']=='pass' and summary['source_report_sha256']==digest(dp)
pairs={tuple(x) for x in summary['affected_subject_seed_tasks']};dispatch=json.loads((code/'configs/dispatch.json').read_text())['tasks']
selected=[t for t in dispatch if (t['subject'],t['seed']) in pairs]
assert {(t['subject'],t['seed']) for t in selected}==pairs
# Fixed source1 official training query, no evaluation phase or performance.
raw=Path('/kaggle/working/sess01_subj01_EEG_ERP.mat')
url='https://s3.ap-northeast-1.wasabisys.com/gigadb-datasets/live/pub/10.5524/100001_101000/100542/session1/s1/'+raw.name
with requests.get(url,stream=True,timeout=(30,300)) as r:
 r.raise_for_status()
 with raw.open('wb') as f:
  for chunk in r.iter_content(1024*1024):f.write(chunk)
assert digest(raw)==json.loads((old/'manifest_s01.json').read_text())['raw_sha256']
schedule=loadmat(unique('schedule.mat'),simplify_cells=True)['rc_order'][:5]
data=loadmat(raw,simplify_cells=True,variable_names=['EEG_ERP_train'])['EEG_ERP_train']
trials=build_trials(data,schedule,'NEURAL_NETWORKS_AND_DEEP_LEARNING',1,1,'train');assert len(trials)==33
eeg=torch.as_tensor(trials[0].eeg).unsqueeze(0);torch.set_num_threads(2)
epsilons=sorted({r['raw_epsilon'] for r in diagnostic['violations']});checks=[]
for epsilon in epsilons:
 for sign in [-1,1]:
  delta=project_applied_delta(eeg,torch.full_like(eeg,sign*epsilon*2),epsilon)
  actual=(eeg+delta)-eeg;assert torch.isfinite(actual).all() and float(actual.abs().max())<=epsilon
 checks.append(dict(epsilon=epsilon,status='strict both-sign actual raw bound pass'))
sourceproof=dict(trial_id=trials[0].trial_id,raw_sha256=digest(raw),checks=checks,scope='source1 first official train character, no model/accuracy outcomes',source_commit=revision)
(out/'source_raw_projection_check.json').write_text(json.dumps(sourceproof,indent=2));raw.unlink()
release=out/'corrective_release';release.mkdir();shutil.copy2(old/'protocol.json',release/'protocol.json')
selected_subjects={t['subject'] for t in selected}
for subject in sorted(selected_subjects):
 mp=old/f'manifest_s{subject:02d}.json';shutil.copy2(mp,release/mp.name)
 receipt=json.loads((old/f'receipt_s{subject:02d}.json').read_text());receipt['execution_code_sha256']=newhash;receipt['git_commit']=revision
 receipt['numerical_correction']=dict(original_receipt_sha256=digest(old/f'receipt_s{subject:02d}.json'),original_source_inventory=oldreceipt['execution_code_sha256'],audit_sha256=digest(dp),summary_sha256=digest(sp),portable_proof_sha256=digest(code/'evidence/portable_config.json'),source_raw_check_sha256=digest(out/'source_raw_projection_check.json'),scope='whole affected tasks, fixed scientific settings, original epsilon unchanged')
 rp=release/f'receipt_s{subject:02d}.json';rp.write_text(json.dumps(receipt,indent=2)+'\n')
 for seed in sorted({t['seed'] for t in selected if t['subject']==subject}):load_execution_release(release/'protocol.json',release/mp.name,rp,subject,seed,json.loads(mp.read_text())['raw_sha256'])
canonical=[dict(task=t,execution='corrective' if (t['subject'],t['seed']) in pairs else 'original_strict_valid') for t in dispatch]
(release/'correction_plan.json').write_text(json.dumps(dict(source_commit=revision,protocol_sha256=ph,strict_violations=13419,changed_files=changes,affected_tasks=selected,affected_task_count=len(selected),reused_original_task_count=51-len(selected),canonical=canonical,scope='whole-task reruns selected only by numerical failure; no performance selection',status='cloud checks passed; receipts require inspection and immutable private preservation before corrected performance'),indent=2))
(out/'corrective_release_complete.json').write_text(json.dumps(dict(source_commit=revision,protocol_sha256=ph,affected_task_count=len(selected),original_reuse_task_count=51-len(selected),source_raw_checks=len(checks),scope='corrective receipt review and fixed source-only raw contract, no corrected performance'),indent=2));print('Corrective release review complete; rerun tasks',len(selected),'reuse',51-len(selected),flush=True)
